package io.coolbox.nlp;
import org.junit.jupiter.api.Test; import java.util.List; import java.util.Set;
import static org.junit.jupiter.api.Assertions.*;
class NlpTest {
 @Test void preprocessAndSimilarity(){assertEquals("hello world",TextProcessor.toLowercase("HELLO WORLD"));assertEquals("hello",TextProcessor.strip("  hello  "));assertEquals(List.of("Quick","brown","fox"),TextProcessor.wordTokenize("Quick brown fox"));assertEquals(3,NlpFunctions.levenshteinDistance("kitten","sitting"));assertEquals(1.0,NlpFunctions.cosineSimilarity(new double[]{1,0},new double[]{1,0}),1e-9);assertEquals(2,TextProcessor.generateNgrams(List.of("a","b","c"),2).size());assertEquals(List.of("red"),TextProcessor.removeStopWords(List.of("the","red"),Set.of("the")));assertEquals(1.0/3,NlpFunctions.jaccardSimilarity(Set.of("a","b"),Set.of("b","c")),1e-9);try(Vocabulary v=new Vocabulary()){v.close();assertThrows(IllegalStateException.class,v::size);}}
 @Test void vocabularyVectorizersAndSequence(){var docs=List.of(List.of("red","blue"),List.of("blue","green"));try(Vocabulary vocab=new Vocabulary().build(docs);BagOfWords bow=new BagOfWords(vocab);TFIDF tfidf=new TFIDF(vocab);SequenceEncoder enc=new SequenceEncoder(vocab,4,true,true)){bow.fit(docs);tfidf.fit(docs);assertEquals(vocab.size(),bow.transform(docs.get(0)).length);assertEquals(2,tfidf.transformBatch(docs).length);assertEquals(4,enc.encode(docs.get(0)).length);assertEquals(docs.get(0),enc.decode(enc.encode(docs.get(0))));}}
 @Test void encodersAndEmbeddingOps(){try(CharacterEncoder chars=new CharacterEncoder().fit(List.of("cat","dog"));OneHotEncoder hot=new OneHotEncoder().fit(List.of("cat","dog"));WordEmbedding emb=new WordEmbedding(4)){assertEquals("cat",chars.decode(chars.encode("cat")));assertEquals(2,hot.encodeBatch(List.of("cat","dog")).length);emb.xavierInit(List.of("cat","dog"));assertEquals(4,emb.getEmbedding("cat").length);assertArrayEquals(new double[]{2,3},NlpFunctions.averageEmbeddings(new double[][]{{1,2},{3,4}}));assertArrayEquals(new double[]{3,4},NlpFunctions.maxPoolingEmbeddings(new double[][]{{1,2},{3,4}}));assertEquals(2,NlpFunctions.createPositionalEncoding(2,4).length);}}
}

